    diff = alpha * scale * (lpw - lpl) + norm_signal
    loss = -ops.logsigmoid(diff)
    if weight is not None:
        weighted_loss = loss * weight
        return weighted_loss.sum() / (weight.sum() + 1e-12)
    else:
        return loss.sum() / loss.numel()

def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)
    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))
    scale = float(extra.get('scale', extra.get('hyperparams', {}).get('scale', 1.0)))
    margin = float(extra.get('margin', 0.1))
    cost_gap = batch['cost_gap']
    cost_gap_norm = ops.zscore(cost_gap)
    diff = alpha * scale * ((lpw - lpl) - margin) + cost_gap_norm
    loss = ops.softplus(-diff)
    if weight is not None:
        weighted_loss = loss * weight
        return weighted_loss.sum() / (weight.sum() + 1e-12)
    else:
        return loss.mean()

def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)
    delta_regret = batch['delta_regret']
    seq_len_gap = batch.get('seq_len_gap', None)
    epsilon = 1e-6
    if seq_len_gap is None:
        seq_len_gap = ops.ones_like(delta_regret)
    delta_regret_norm = delta_regret / (seq_len_gap + epsilon)
    margin = float(extra.get('margin', 0.5))
    alpha = float(extra.get('alpha', 1.0))
    scaled_diff = alpha * (lpw - lpl)
    margin_diff = margin - (scaled_diff + delta_regret_norm)
    loss_per_pair = ops.relu(margin_diff)
    if weight is not None:
        weighted_loss = loss_per_pair * weight
        return weighted_loss.sum() / (weight.sum() + 1e-12)
    else:
        return loss_per_pair.mean()

