def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)
    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))
    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))
    clamp_min = float(extra.get('hyperparams', {}).get('clamp_min', -5.0))
    clamp_max = float(extra.get('hyperparams', {}).get('clamp_max', 5.0))
    cost_gap = batch.get('cost_gap', None)
    if cost_gap is None:
        raise ValueError('cost_gap signal is required')
    pref_signal = ops.zscore(cost_gap)
    pref_signal = ops.clamp(pref_signal, clamp_min, clamp_max)
    diff = alpha * scale * (lpw - lpl) + pref_signal
    loss = -ops.logsigmoid(diff)
    if weight is not None:
        weighted_loss = loss * weight
        return weighted_loss.sum() / (weight.sum() + 1e-12)
    else:
        return loss.sum() / loss.numel()
